using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json.Linq;

namespace DungeonContract
{
    public sealed partial class DcP1World
    {
        private JObject runtimeState;
        private readonly Dictionary<string,JObject> runtimeRecords=new Dictionary<string,JObject>();
        private readonly HashSet<string> runtimeLive=new HashSet<string>();
        private readonly Queue<JObject> v6ProjectileRecords=new Queue<JObject>();
        private static void Put(JObject value,string key,object data){if(value[key] is JValue cell)cell.Value=data;else value[key]=data==null?JValue.CreateNull():new JValue(data);}
        private static void Put(JObject value,string key,int data){if(value[key] is JValue cell){if(cell.Value is int i&&i==data||cell.Value is long l&&l==data)return;cell.Value=data;}else value[key]=new JValue(data);}
        private static void Put(JObject value,string key,long data){if(value[key] is JValue cell){if(cell.Value is long l&&l==data||cell.Value is int i&&i==data)return;cell.Value=data;}else value[key]=new JValue(data);}
        private static void Put(JObject value,string key,uint data)=>Put(value,key,(long)data);
        private static void Put(JObject value,string key,float data){if(value[key] is JValue cell){if(cell.Value is float f&&f==data)return;cell.Value=data;}else value[key]=new JValue((object)data);}
        private static void Put(JObject value,string key,bool data){if(value[key] is JValue cell){if(cell.Value is bool b&&b==data)return;cell.Value=data;}else value[key]=new JValue(data);}
        private static void Put(JObject value,string key,string data){if(data==null){if(value[key]?.Type!=JTokenType.Null)value[key]=JValue.CreateNull();return;}if(value[key] is JValue cell){if(cell.Type==JTokenType.String&&(string)cell.Value==data)return;cell.Value=data;}else value[key]=new JValue(data);}
        private JObject Record(string key){runtimeLive.Add(key);if(!runtimeRecords.TryGetValue(key,out var value)){value=V6&&key.StartsWith("projectile:",StringComparison.Ordinal)&&v6ProjectileRecords.Count>0?v6ProjectileRecords.Dequeue():new JObject();runtimeRecords[key]=value;}return value;}
        private static void Coordinates(JObject value,int room,UnityEngine.Vector2 point){Put(value,"room_id",room);Put(value,"x",point.x);Put(value,"y",point.y);}
        private static void ResetArray(JObject value,string key){if(value[key] is JArray list)list.Clear();else value[key]=new JArray();}
        public JObject RuntimeSnapshot()
        {
            if(!P2)return Snapshot();
            if(runtimeState==null){runtimeState=DcV6Profile.P5((string)manifest["config"]?["definition_id"])?new JObject{["schema_version"]=3,["run_id"]=manifest["run_id"].DeepClone(),["practice"]=Practice}:Snapshot();runtimeRecords.Clear();}
            runtimeLive.Clear();var value=runtimeState;
            Put(value,"world_frame_id",WorldTick);Put(value,"elapsed_ms",now);Put(value,"room",MaximumRoom);Put(value,"safe_node",safeNode);Put(value,"safe_remaining_ms",safeNode<0?0:Math.Max(0,safeUntil-now));Put(value,"reinforcement_remaining",reinforcementRemaining);Put(value,"projectile_load",ProjectileLoad);Put(value,"outcome",Outcome);Put(value,"reason",terminalReason);Put(value,"boss_warning_remaining_ms",rooms[5].Status=="warning"?Math.Max(0,rooms[5].WarningAt-combatNow):0);
            ResetArray(value,"completed");foreach(var item in rooms.Take(6))((JArray)value["completed"]).Add(item.Status=="cleared");
            ResetArray(value,"rooms");foreach(var item in rooms){var record=Record("room:"+item.Index);Put(record,"index",item.Index);Put(record,"id",(string)Layout(item.Index)["id"]);Put(record,"connector",item.Connector);Put(record,"exists",item.Exists);Put(record,"status",item.Status);Put(record,"wave",item.Wave);Put(record,"pending",item.Pending.Count);Put(record,"mechanism_complete",item.Mechanism);Put(record,"warning_remaining_ms",Math.Max(0,item.WarningAt-combatNow));Put(record,"enemies_remaining",item.Pending.Count+spawnReservations.Count(spawn=>spawn.Room==item.Index&&spawn.Recovering==null)+enemies.Count(enemy=>enemy.Room==item.Index&&enemy.Health>0));((JArray)value["rooms"]).Add(record);}
            ResetArray(value,"players");foreach(var player in players.Values.OrderBy(item=>item.Slot))
            {
                var record=Record("player:"+player.ID);Coordinates(record,player.Room,player.Position);Put(record,"player_id",player.ID);Put(record,"slot",player.Slot);Put(record,"loadout_id",player.Loadout);Put(record,"health",player.Health);Put(record,"shield",player.Shield);Put(record,"damage",player.Damage);Put(record,"deaths",player.Deaths);Put(record,"connected",player.Connected);Put(record,"left",player.Left);
                Put(record,"active_weapon_id",WeaponID(player));Put(record,"melee_equipped",player.MeleeEquipped);Put(record,"weapon_revision",player.WeaponRevision);Put(record,"release_required",player.ReleaseRequired);Put(record,"last_action_sequence",player.LastActionSequence);Put(record,"charge_action_id",player.ChargeAction);Put(record,"switch_remaining_ms",Math.Max(0,player.SwitchAt-now));Put(record,"ranged_ready_ms",player.RangedReady);Put(record,"melee_ready_ms",player.MeleeReady);Put(record,"hurt_protection_remaining_ms",Math.Max(0,player.HurtUntil-now));Put(record,"dodge_speed",player.DodgeSpeed);Put(record,"magazine",player.Magazine);Put(record,"magazine_max",MagazineSize(player));Put(record,"reload_remaining_ms",Math.Max(0,player.ReloadUntil-now));Put(record,"charging",player.Charging);Put(record,"charge_ms",player.Charging?now-player.ChargeAt:0);Put(record,"secondary_remaining_ms",Math.Max(0,player.SecondaryAt-now));Put(record,"life_state",player.Life);Put(record,"knockdowns",player.Knockdowns);Put(record,"light_attacks",player.LightCount);Put(record,"heavy_attacks",player.HeavyCount);
                Put(record,"last_input_sequence",player.Ack);Put(record,"dodge_direction_x",player.DodgeDirection.x);Put(record,"dodge_direction_y",player.DodgeDirection.y);Put(record,"dodge_duration_remaining_ms",Math.Max(0,player.DodgeUntil-now));Put(record,"dodge_remaining_ms",Math.Max(0,player.DodgeAt-now));Put(record,"ability_remaining_ms",Math.Max(0,player.AbilityAt-now));Put(record,"protected_remaining_ms",Math.Max(0,player.ProtectedUntil-now));Put(record,"interaction_remaining_ms",player.InteractionTarget==null?0:Math.Max(0,Number(config["player"],"interaction_ms")-(now-player.InteractionAt)));Put(record,"supply_used",player.Claims.Contains("supply_court"));Put(record,"respawn_remaining_ms",player.Reinforcement==null?-1:Math.Max(0,player.RespawnAt-now));Put(record,"choice",safeNode>=0&&player.Choices.TryGetValue(safeNode,out var choice)?choice:null);
                ResetArray(record,"explored_rooms");foreach(var item in player.Explored.OrderBy(item=>item))((JArray)record["explored_rooms"]).Add(item);ResetArray(record,"upgrades");foreach(var item in player.Upgrades)((JArray)record["upgrades"]).Add(item);ResetArray(record,"candidates");foreach(var item in Candidates(player.ID))((JArray)record["candidates"]).Add(item);((JArray)value["players"]).Add(record);
            }
            ResetArray(value,"enemies");foreach(var enemy in enemies.Where(item=>item.Health>0)){var record=Record("enemy:"+enemy.ID);Coordinates(record,enemy.Room,enemy.Position);Put(record,"id",enemy.ID);Put(record,"kind",enemy.Kind);Put(record,"health",enemy.Health);Put(record,"maximum",enemy.Maximum);Put(record,"warning",enemy.WarningUntil>combatNow?enemy.Warning:"");Put(record,"warning_remaining_ms",Math.Max(0,enemy.WarningUntil-combatNow));Put(record,"warning_x",enemy.Origin.x);Put(record,"warning_y",enemy.Origin.y);Put(record,"aim_x",enemy.Aim.x);Put(record,"aim_y",enemy.Aim.y);Put(record,"phase",enemy.Kind=="boss"&&enemy.Health*100<=enemy.Maximum*50?2:1);((JArray)value["enemies"]).Add(record);}
            ResetArray(value,"projectiles");foreach(var projectile in projectiles){var record=Record("projectile:"+projectile.ID);if((string)record["id"]!=projectile.ID)projectile.RuntimeSnapshotBound=false;Coordinates(record,projectile.Room,projectile.Position);if(!V6||!projectile.RuntimeSnapshotBound){Put(record,"id",projectile.ID);Put(record,"enemy",projectile.Enemy);Put(record,"speed",projectile.Speed);Put(record,"radius",projectile.CollisionRadius);Put(record,"unbounded",projectile.Unbounded);}Put(record,"bounces",projectile.Bounces);Put(record,"penetrations",projectile.Penetration);Put(record,"remaining_range",projectile.Unbounded?null:(object)projectile.Remaining);Put(record,"direction_x",projectile.Direction.x);Put(record,"direction_y",projectile.Direction.y);((JArray)value["projectiles"]).Add(record);}
            ResetArray(value,"turrets");foreach(var turret in turrets){var record=Record("turret:"+turret.ID);Coordinates(record,turret.Room,turret.Position);Put(record,"id",turret.ID);Put(record,"owner",turret.Owner);Put(record,"damage",turret.BaseDamage);((JArray)value["turrets"]).Add(record);}
            ResetArray(value,"covers");foreach(var cover in covers){var record=Record("cover:"+cover.ID);Coordinates(record,cover.Room,cover.Position);Put(record,"id",cover.ID);Put(record,"health",cover.Health);Put(record,"revision",cover.Revision);((JArray)value["covers"]).Add(record);}
            ResetArray(value,"fields");foreach(var field in fields){var record=Record("field:"+field.ID);Coordinates(record,field.Room,field.Position);Put(record,"id",field.ID);Put(record,"kind",field.Kind);Put(record,"radius",Distance(Kit(players[field.Owner].Loadout)["secondary"],"radius_milli_tiles"));((JArray)value["fields"]).Add(record);}
            ResetArray(value,"traps");foreach(var trap in traps){var record=Record("trap:"+trap.ID);Coordinates(record,trap.Room,trap.Position);Put(record,"id",trap.ID);Put(record,"phase",trap.Phase);Put(record,"remaining_ms",Math.Max(0,trap.Until-combatNow));((JArray)value["traps"]).Add(record);}
            ResetArray(value,"spawn_reservations");foreach(var spawn in spawnReservations){var record=Record("spawn:"+spawn.ID);Coordinates(record,spawn.Room,spawn.Position);Put(record,"id",spawn.ID);Put(record,"kind",spawn.Kind);Put(record,"remaining_ms",Math.Max(0,spawn.Until-combatNow));((JArray)value["spawn_reservations"]).Add(record);}
            ResetArray(value,"effects");foreach(var effect in effects.Where(effect=>now-(long)effect["at"]<=200))((JArray)value["effects"]).Add(effect.DeepClone());
            foreach(var key in runtimeRecords.Keys.Where(key=>!runtimeLive.Contains(key)).ToArray()){var old=runtimeRecords[key];runtimeRecords.Remove(key);if(V6&&key.StartsWith("projectile:",StringComparison.Ordinal)&&v6ProjectileRecords.Count<1024){if(old.Parent!=null)old.Remove();v6ProjectileRecords.Enqueue(old);}}
            P3Snapshot(value);P4Snapshot(value);if(V5)V5Snapshot(value,V6);if(V6){V6Snapshot(value,true);foreach(var projectile in projectiles)projectile.RuntimeSnapshotBound=true;}return value;
        }
    }
